namespace Ordering;

/// <summary>Imports orders from a batch of delimited rows.</summary>
public sealed class OrderImporter
{
    private readonly OrderRepository _repository;

    public OrderImporter(OrderRepository repository) => _repository = repository;

    public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
    {
        var imported = new List<Order>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            if (!TryParseOrder(row, seen, out var order))
                continue;

            _repository.Add(order);
            imported.Add(order);
        }

        return imported;
    }

    private static bool TryParseOrder(string row, HashSet<string> seen, out Order order)
    {
        order = null!;
        if (!TryReadHeader(row, seen, out var parts, out var recordType, out var reference))
            return false;
        if (!TryCreateOrder(recordType, reference, out order))
            return false;

        AddOrderLines(order, parts);
        return order.Lines.Count > 0;
    }

    private static bool TryReadHeader(
        string row,
        HashSet<string> seen,
        out string[] parts,
        out string recordType,
        out string reference)
    {
        parts = Array.Empty<string>();
        recordType = string.Empty;
        reference = string.Empty;

        if (string.IsNullOrWhiteSpace(row))
            return false;

        parts = row.Split(',');
        if (parts.Length < 4)
            return false;

        recordType = parts[0].Trim();
        reference = parts[1].Trim();
        return reference.Length > 0 && seen.Add(reference);
    }

    private static bool TryCreateOrder(string recordType, string reference, out Order order)
    {
        switch (recordType)
        {
            case "H":
            case "ORDER":
                order = new Order { Reference = reference, Channel = OrderChannel.Web };
                return true;
            case "M":
                order = new Order { Reference = reference, Channel = OrderChannel.Marketplace };
                return true;
            default:
                order = null!;
                return false;
        }
    }

    private static void AddOrderLines(Order order, string[] parts)
    {
        for (var i = 2; i + 1 < parts.Length; i += 2)
        {
            var sku = parts[i].Trim();
            if (sku.Length == 0)
                continue;
            if (!int.TryParse(parts[i + 1], out var quantity) || quantity <= 0)
                continue;

            order.Lines.Add(new OrderLine
            {
                Sku = sku,
                Quantity = quantity,
                UnitPrice = GetUnitPrice(sku, quantity)
            });
        }
    }

    private static decimal GetUnitPrice(string sku, int quantity)
    {
        if (sku.StartsWith("PRM", StringComparison.Ordinal) && quantity > 10)
            return 9.99m;
        if (sku.StartsWith("STD", StringComparison.Ordinal))
            return 4.99m;

        return 0m;
    }
}
